def transform(grid):
    out = [row[:] for row in grid]
    n = 5
    a = [[grid[r][c] != grid[r][19] for c in range(1, 6)] for r in range(1, 6)]

    # The isolated/extreme pixel of the first pattern identifies the corner
    # whose triangular half comes from the second pattern.
    candidates = []
    for r in range(n):
        for c in range(n):
            if a[r][c]:
                d = (r - 2) ** 2 + (c - 2) ** 2
                candidates.append((d, -r, -c, r, c))
    _, _, _, ar, ac = max(candidates)
    if ar <= 2 and ac <= 2:
        corner = "NW"
    elif ar >= 2 and ac <= 2:
        corner = "SW"
    elif ar <= 2:
        corner = "NE"
    else:
        corner = "SE"

    for r in range(n):
        for c in range(n):
            if corner == "NW":
                use_second = r + c <= 4
            elif corner == "SW":
                use_second = r >= c
            elif corner == "NE":
                use_second = r <= c
            else:
                use_second = r + c >= 4
            source_col = (6 if use_second else 12) + c + 1
            out[r + 1][18 + c + 1] = grid[r + 1][source_col]
    return out
